// OLIVE BRANCH — court-export hash chain, parity with the TypeScript engine.
//
// Every case comes from packages/ledger/test/vectors.json, generated by
// tools/gen-ledger-vectors.mjs from packages/ledger/src/ledger.ts (the ledger
// suite fails CI if they disagree). lib/court_export.dart's computeEntryHash,
// verifyChain and certify must give the same answers, so the phone's "this
// export is intact" and the server's can never differ. Each vector is its own
// test, so a failure names the case.
import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:olive_client/court_export.dart';

final Map<String, dynamic> v =
    jsonDecode(File('../packages/ledger/test/vectors.json').readAsStringSync()) as Map<String, dynamic>;

LogEntry _entry(Map<String, dynamic> m) => LogEntry(
    seq: m['seq'] as int, childId: m['childId'] as String, authorId: m['authorId'] as String,
    at: m['at'] as String, body: m['body'] as String, prevHash: m['prevHash'] as String,
    hash: m['hash'] as String);

String _kind(ChainFaultKind k) => switch (k) {
      ChainFaultKind.contentAltered => 'content_altered',
      ChainFaultKind.chainBroken => 'chain_broken',
      ChainFaultKind.sequenceGap => 'sequence_gap',
      ChainFaultKind.badGenesis => 'bad_genesis',
      ChainFaultKind.timeTravel => 'time_travel',
    };

void main() {
  final Map<String, dynamic> chains = v['chains'] as Map<String, dynamic>;
  for (final String name in chains.keys) {
    final Map<String, dynamic> c = chains[name] as Map<String, dynamic>;
    final List<LogEntry> entries =
        (c['entries'] as List<dynamic>).map((dynamic e) => _entry(e as Map<String, dynamic>)).toList();
    group('chain "$name"', () {
      test('entry hashes', () {
        final List<dynamic> want = c['hashes'] as List<dynamic>;
        for (int i = 0; i < entries.length; i++) {
          final LogEntry e = entries[i];
          expect(
              computeEntryHash(seq: e.seq, childId: e.childId, authorId: e.authorId, at: e.at,
                  body: e.body, prevHash: e.prevHash),
              want[i], reason: 'entry $i');
        }
      });
      test('verifyChain', () {
        final ChainVerification r = verifyChain(entries);
        final Map<String, dynamic> want = c['verify'] as Map<String, dynamic>;
        expect(r.ok, want['ok']);
        expect(r.faults.map((ChainFault f) => '${_kind(f.kind)}@${f.seq}').toList(),
            (want['faults'] as List<dynamic>)
                .map((dynamic f) => '${(f as Map<String, dynamic>)['kind']}@${f['seq']}').toList());
      });
      test('certify', () {
        final Map<String, dynamic> want = c['attestation'] as Map<String, dynamic>;
        final Attestation a = certify(entries, want['childId'] as String, want['generatedAt'] as String);
        expect(a.entryCount, want['entryCount']);
        expect(a.firstSeq, want['firstSeq']);
        expect(a.lastSeq, want['lastSeq']);
        expect(a.headHash, want['headHash']);
        expect(a.bundleHash, want['bundleHash']);
        expect(a.chainVerified, want['chainVerified']);
        expect(a.statement, want['statement']);
      });
    });
  }
}
